import React from 'react';

type MediaItem = {
  title: string;
  description: string;
  type: string;
};

export default function MediaGrid({ items }: { items: MediaItem[] }) {
  return (
    <div className="grid grid-cols-1 md:grid-cols-2 gap-8 py-12">
      {items.map((item: MediaItem, index: number) => (
        <div key={index} className="group p-6 border rounded-xl hover:shadow-xl transition-all duration-500 bg-white">
          <div className="aspect-video bg-gray-100 rounded-lg mb-4 overflow-hidden relative flex items-center justify-center">
            <span className="text-gray-400">{item.type === 'image' ? `[Image: ${item.title}]` : `[Video: ${item.title}]`}</span>
          </div>
          <h3 className="text-xl font-bold mb-2 group-hover:text-blue-600 transition-colors">{item.title}</h3>
          <p className="text-gray-600 text-sm leading-relaxed">{item.description}</p>
        </div>
      ))}
    </div>
  );
}
